function createCategories(){


    let cats=[
        "All",
        ...new Set(
            games.map(g=>g.category)
        )
    ];



    cats.forEach((cat,index)=>{


        let y=
        260+(index*55);



        let button =
        document.createElementNS(
        "http://www.w3.org/2000/svg",
        "g"
        );



        button.innerHTML=`

        <rect
        x="60"
        y="${y-30}"
        width="170"
        height="40"
        rx="20"
        fill="#ffffff15"/>


        <text
        x="145"
        y="${y}"
        text-anchor="middle"
        fill="white"
        font-size="16"
        font-family="Arial">
        ${cat}
        </text>

        `;



        button.onclick=()=>{


            if(cat==="All")
                displayGames(games);

            else

                displayGames(
                    games.filter(
                    g=>g.category===cat
                    )
                );


        };



        categoryLayer.appendChild(button);


    });


}





function displayGames(list){


    gamesLayer.innerHTML="";



    list.forEach((game,index)=>{


        let x=
        330+
        ((index%3)*260);



        let y=
        260+
        (Math.floor(index/3)*260);



        let card=
        document.createElementNS(
        "http://www.w3.org/2000/svg",
        "g"
        );



        card.innerHTML=`

        <rect
        x="${x}"
        y="${y}"
        width="230"
        height="220"
        rx="25"
        fill="url(#card)"/>


        <text
        x="${x+115}"
        y="${y+40}"
        text-anchor="middle"
        fill="white"
        font-size="20"
        font-family="Arial"
        font-weight="bold">
        ${game.name}
        </text>


        <text
        x="${x+115}"
        y="${y+75}"
        text-anchor="middle"
        fill="#aaa"
        font-size="14"
        font-family="Arial">
        ${game.category}
        </text>


        <rect
        x="${x+35}"
        y="${y+120}"
        width="160"
        height="45"
        rx="22"
        fill="white"/>


        <text
        x="${x+115}"
        y="${y+150}"
        text-anchor="middle"
        fill="black"
        font-size="16"
        font-family="Arial">
        PLAY
        </text>

        `;



        card.onclick=()=>{


            window.open(
            game.url,
            "_blank"
            );


        };



        gamesLayer.appendChild(card);


    });


}
